SubProceso CobrarConIva(total Como Entero Por Referencia)
  total <- total + total * 18 div 100;
  total <- total - total div 10;
  Escribir "Total: ", total;
FinSubProceso

Algoritmo Caja
  Definir compra Como Entero;
  Leer compra;
  CobrarConIva(compra);
FinAlgoritmo

